    int year;
    float weight;
    Motor motor; // Composition

public:
    Vehicle(std::string b, int y, float w) : brand(b), year(y), weight(w) {}
    virtual ~Vehicle() {}

    // Perimeter methods (Encapsulation)
    void setBrand(std::string b) { brand = b; }
    std::string getBrand() { return brand; }
    void setYear(int y) { year = y; }
    int getYear() { return year; }
    void setWeight(float w) { weight = w; }
    float getWeight() { return weight; }

    virtual void displayInfo() = 0; // Polymorphic method
};

